package com.cpf.batch.agent; import com.cpf.batch.agent.internal.*; import com.cpf.batch.api.*; import org.springframework.core.io.FileSystemResource; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.nio.file.Path; import java.time.Instant; import java.util.UUID;
@RestController @RequestMapping("/api/v1/agent") public class AgentController { private final ApprovedCommandCatalog catalog;private final ArtifactInstaller installer;private final ServiceManager manager;private final RuntimeControlProxy runtime;private final LogArchiveService logs;public AgentController(ApprovedCommandCatalog c,ArtifactInstaller i,ServiceManager m,RuntimeControlProxy r,LogArchiveService l){catalog=c;installer=i;manager=m;runtime=r;logs=l;} @PostMapping("/artifacts/install") AgentCommandResult install(@RequestBody AgentArtifactRequest q){String id=UUID.randomUUID().toString();Instant s=Instant.now();try{catalog.requireAllowed("INSTALL_ARTIFACT");var x=installer.install(q);return result(id,q.serviceId(),"INSTALL_ARTIFACT",CommandState.SUCCEEDED,"INSTALLED","installed",x.version(),s);}catch(SecurityException e){return result(id,q.serviceId(),"INSTALL_ARTIFACT",CommandState.FAILED,"SECURITY_REJECTED","request rejected",null,s);}catch(Exception e){return result(id,q.serviceId(),"INSTALL_ARTIFACT",CommandState.FAILED,"INSTALL_FAILED",com.cpf.batch.runtime.SensitiveTextSanitizer.sanitize(e.getMessage()),null,s);}} @PostMapping("/services/{id}/start") AgentCommandResult start(@PathVariable String id){return svc(id,"START",ServiceManager.Action.START);}@PostMapping("/services/{id}/stop") AgentCommandResult stop(@PathVariable String id){return svc(id,"STOP",ServiceManager.Action.STOP);}@PostMapping("/services/{id}/restart") AgentCommandResult restart(@PathVariable String id){return svc(id,"RESTART",ServiceManager.Action.RESTART);}@PostMapping("/services/{id}/rollback") AgentCommandResult rollback(@PathVariable String id){String c=UUID.randomUUID().toString();Instant s=Instant.now();try{catalog.requireAllowed("ROLLBACK");manager.execute(id,ServiceManager.Action.STOP);String v=installer.rollback(id);var x=manager.execute(id,ServiceManager.Action.START);return result(c,id,"ROLLBACK",x.success()?CommandState.SUCCEEDED:CommandState.FAILED,x.success()?"ROLLED_BACK":"ROLLBACK_START_FAILED",x.output(),v,s);}catch(Exception e){return result(c,id,"ROLLBACK",CommandState.FAILED,"ROLLBACK_FAILED",com.cpf.batch.runtime.SensitiveTextSanitizer.sanitize(e.getMessage()),null,s);}} @PostMapping("/services/{id}/drain") AgentCommandResult drain(@PathVariable String id){return runtime(id,"DRAIN","drain");}@PostMapping("/services/{id}/resume") AgentCommandResult resume(@PathVariable String id){return runtime(id,"RESUME","resume");}@GetMapping("/services/{id}/logs") ResponseEntity<FileSystemResource> logs(@PathVariable String id)throws Exception{catalog.requireAllowed("COLLECT_LOGS");Path z=logs.collect(id);return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+z.getFileName()+"\"").body(new FileSystemResource(z));} private AgentCommandResult runtime(String id,String cmd,String op){String c=UUID.randomUUID().toString();Instant s=Instant.now();try{catalog.requireAllowed(cmd);runtime.invoke(id,op);return result(c,id,cmd,CommandState.SUCCEEDED,cmd+"ED","Runtime "+op+" accepted",null,s);}catch(Exception e){return result(c,id,cmd,CommandState.FAILED,cmd+"_FAILED",com.cpf.batch.runtime.SensitiveTextSanitizer.sanitize(e.getMessage()),null,s);}} private AgentCommandResult svc(String id,String cmd,ServiceManager.Action a){String c=UUID.randomUUID().toString();Instant s=Instant.now();try{catalog.requireAllowed(cmd);var x=manager.execute(id,a);return result(c,id,cmd,x.success()?CommandState.SUCCEEDED:CommandState.FAILED,x.success()?"OK":"SERVICE_COMMAND_FAILED",x.output(),null,s);}catch(Exception e){return result(c,id,cmd,CommandState.FAILED,"SERVICE_COMMAND_FAILED",com.cpf.batch.runtime.SensitiveTextSanitizer.sanitize(e.getMessage()),null,s);}} private AgentCommandResult result(String id,String svc,String cmd,CommandState st,String code,String msg,String ver,Instant s){return new AgentCommandResult(id,svc,cmd,st,code,msg,ver,s,Instant.now());} }
